/** Shared API types for yimeng Core (generated by hand from openapi; keep in sync). */

export type ID = string;

export interface ErrorBody {
  error: string;
  message: string;
}

export interface Page<T> {
  items: T[];
  total: number;
  limit: number;
  offset: number;
}

export interface Artist {
  id: ID;
  name: string;
  sort_name?: string;
  mb_id?: string;
  album_count: number;
  track_count: number;
  /** Set when an admin chose an image: GET /api/artists/{id}/image */
  image_updated_at?: string;
}

export interface Album {
  id: ID;
  title: string;
  artist_name: string;
  artists: ArtistRef[];
  year?: number;
  genre?: string;
  track_count: number;
  disc_count?: number;
  duration_ms: number;
  has_cover: boolean;
  favorite?: boolean;
  rating?: number;
  created_at: string;
}

export interface ArtistRef {
  id: ID;
  name: string;
  role: string;
}

export interface Track {
  id: ID;
  title: string;
  artist_name: string;
  artists: ArtistRef[];
  album_id?: ID;
  album_title?: string;
  disc_no?: number;
  track_no?: number;
  year?: number;
  genre?: string;
  duration_ms: number;
  format?: string;
  play_count?: number;
  favorite?: boolean;
  rating?: number;
  created_at: string;
  /** A–Z index key (pinyin initial for Chinese titles, "#" otherwise) */
  sort_letter?: string;
  /** "local" or a platform id (netease | qq | kugou) */
  origin?: string;
}

export interface PlayerState {
  player_id: ID;
  transport: "idle" | "buffering" | "playing" | "paused";
  position_ms: number;
  updated_at: string;
  current_index: number;
  queue_length: number;
  repeat: "off" | "all" | "one";
  shuffle: boolean;
  online?: boolean;
  sleep_until?: string;
  track?: TrackRef;
}

export interface TrackRef {
  id: ID;
  title: string;
  artist_name: string;
  album_id?: ID;
  album_title?: string;
  duration_ms: number;
}

export interface SystemInfo {
  version: string;
  uptime_s: number;
  features: Record<string, boolean>;
}

export interface HealthReport {
  tracks: number;
  albums: number;
  artists: number;
  missing_files: number;
  no_cover_albums: number;
  no_genre_tracks: number;
  by_format: Record<string, number>;
}

export interface Stats {
  tracks: number;
  albums: number;
  artists: number;
  play_count: number;
  favorites: number;
  playlists: number;
  top_artists: StatItem[];
  top_tracks: StatItem[];
}

export interface StatItem {
  id: ID;
  name: string;
  count: number;
}

// ── Lyrics API for apps (GET /api/v1/lyrics/search | /best) ─────────────────

export type LyricsProvider = "user" | "local" | "lrclib" | "netease" | "qq" | "kugou";

export interface LyricsQuery {
  title: string;
  artist?: string;
  album?: string;
  duration_ms?: number;
  isrc?: string;
}

/** Points per factor; max title 40, artist 30, album 5, duration 15, synced 5, translation 2, reliability 3. */
export interface LyricsScoreBreakdown {
  title: number;
  artist: number;
  album: number;
  duration: number;
  synced: number;
  translation: number;
  reliability: number;
  /** -1 when unknown */
  duration_delta_ms: number;
  /** 1 = none; 0.3 when the title does not match */
  penalty: number;
}

export interface LyricsSearchCandidate {
  id: string;
  provider: LyricsProvider | string;
  title: string;
  artist: string;
  album?: string;
  duration_ms?: number;
  synced: boolean;
  has_translation: boolean;
  /** 0..100 */
  score: number;
  score_breakdown?: LyricsScoreBreakdown;
  preview: string[];
}

export interface LyricsSearchResult {
  query?: LyricsQuery;
  found: boolean;
  /** "暂无歌词" when found=false */
  message?: string;
  items: LyricsSearchCandidate[];
}

export interface LyricsBestLine {
  t_ms: number;
  text: string;
  trans?: string;
}

export type LyricsBest =
  | { query?: LyricsQuery; found: false; message: string }
  | {
      query?: LyricsQuery;
      found: true;
      id: string;
      provider: LyricsProvider | string;
      title: string;
      artist: string;
      album?: string;
      duration_ms?: number;
      synced: boolean;
      score: number;
      score_breakdown?: LyricsScoreBreakdown;
      offset_ms: number;
      lrc: string;
      plain: string;
      translation: string;
      romanization: string;
      lines: LyricsBestLine[];
    };

// ── Admin: artist images, runtime server settings ─────────────────────────

export interface ArtistImageCandidate {
  provider: string;
  external_id?: string;
  name: string;
  image_url: string;
  followers?: number;
  score: number;
}

export type FillSourceId = "spotify" | "netease" | "qq" | "kugou" | "musicbrainz";

export interface CacheKindStats { origin: string; kind: string; entries: number; bytes: number; fresh: number; stale: number }
/** GET /api/settings/cache (admin). */
export interface CacheStats {
  entries: number; bytes: number; max_bytes: number; kinds: CacheKindStats[];
  counters: Record<"hits" | "stale_served" | "misses" | "coalesced" | "negative_hits" | "errors" | "stale_on_error" | "evicted", number>;
}

export interface ServerSettings {
  watch_mode: "auto" | "fsnotify" | "poll" | "off";
  /** Go duration, "0" = never */
  rescan_interval: string;
  musicbrainz_enabled: boolean;
  musicbrainz_contact: string;
  /** ordered; empty = background metadata fill off */
  fill_sources: FillSourceId[];
  fill_per_minute: number;
}

export interface ServerSettingsResponse {
  settings: ServerSettings;
  fill_source_ids: FillSourceId[];
}

// ---- App API (D45/D46/D47) ----
export interface Session { access_token: string; refresh_token: string; expires_in: number; token_type: "Bearer" }
export type PlatformCapability = "search" | "stream" | "lyrics" | "charts" | "daily" | "fm" | "recommend_playlists" | "user_playlists";
export interface ServerPlatform { origin: string; name: string; enabled: boolean; logged_in: boolean; nickname?: string; vip?: boolean; capabilities: PlatformCapability[] }
export interface ServerInfo { name: string; version: string; api_version: string; schema_version: number; authenticated: boolean; features: Record<string, boolean>; platforms: ServerPlatform[] }
export interface CoverRef { url: string; blurhash?: string | null; colors?: string[] }
export interface ListEnvelope<T> { items: T[]; total: number; cursor: string | null; next_cursor: string | null; updated_at?: string }
export type Entitlement = "full" | "preview" | "unavailable";
export interface AppTrackFields { playable: boolean; entitlement?: Entitlement; unplayable_reason?: string | null; has_lyrics?: boolean; album?: { id: string; name: string } | null; cover?: CoverRef; stream_url?: string }
export interface PlaybackProgress { track_id: string; position_ms: number; duration_ms: number; finished: boolean; device_id?: string; updated_at: string }
export interface LyricWord { t_ms: number; d_ms: number; text: string }
export interface MergedLyricLine { t_ms: number; text: string; trans?: string; roma?: string; words?: LyricWord[] }
export interface LyricsSources { text?: string; words?: string; trans?: string; roma?: string }
export interface TrackDream { track_id: string; colors: string[] | null; blurhash: string | null; tags: string[]; bpm: number | null }
export interface ApiError { error: string; code: string; message: string }
